(() => {
'use strict';
const COLORS=['#4478ee','#f26d5f','#2cc9c2','#e5a92f','#8a65d8','#68758a'];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#canvas'), edges=$('#edgesLayer'), wrap=$('#mapView');
let state=null, selectedId=null, editingId=null, connectFrom=null, history=[], historyIndex=-1;
let view={x:0,y:0,scale:1}, drag=null, pan=null, currentScreen='map', currentFilter='recent', searchQuery='', detailsTimer=null;
const uid=()=>`n${Math.random().toString(36).slice(2,10)}`, mid=()=>`m${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
const node=(text,parentId,color=null,x=0,y=0)=>({id:uid(),text,parentId,color,x,y,collapsed:false,note:'',link:'',task:{assignee:'',due:'',done:false},comments:[]});
function cleanNode(n){return {...node(n.text||'Nova ideia',n.parentId??null,n.color,n.x||0,n.y||0),...n,task:{assignee:'',due:'',done:false,...(n.task||{})},comments:n.comments||[]};}
function normalize(data){const nodes={};Object.values(data.nodes||{}).forEach(n=>nodes[n.id]=cleanNode(n));return {id:data.id||mid(),title:data.title||'Mapa sem título',nodes,rootId:data.rootId,favorite:!!data.favorite,connections:data.connections||[],updatedAt:data.updatedAt};}
function starter(){
 const root=node('Plano Mestre 2026',null,null,2820,1900); const nodes={[root.id]:root};
 const specs=[['Visão & propósito','#f26d5f',2470,1660],['Projetos prioritários','#2cc9c2',3240,1660],['Pessoas & recursos','#e5a92f',2460,2180],['Próximos passos','#4478ee',3250,2160]];
 specs.forEach(([t,c,x,y],i)=>{const n=node(t,root.id,c,x,y);nodes[n.id]=n; const children=i===0?['Objetivo principal','Princípios']:i===1?['Produto digital','Operação']:i===2?['Responsáveis','Ferramentas']:['Esta semana','Depois'];children.forEach((label,j)=>{const child=node(label,n.id,null,x+(x<2820?-230:230),y+(j?100:-55));nodes[child.id]=child;});});
 return {id:mid(),title:'Meu Plano Mestre',nodes,rootId:root.id,favorite:false,connections:[]};
}
const children=id=>Object.values(state.nodes).filter(n=>n.parentId===id);
function branchColor(n){if(n.color)return n.color;if(n.parentId&&state.nodes[n.parentId])return branchColor(state.nodes[n.parentId]);return '#8d98aa';}
function hidden(n){let p=state.nodes[n.parentId];while(p){if(p.collapsed)return true;p=state.nodes[p.parentId]}return false;}
function snapshot(){return JSON.stringify({...state,updatedAt:undefined});}
function commit(){if(!state)return;const snap=snapshot();if(history[historyIndex]!==snap){history=history.slice(0,historyIndex+1);history.push(snap);historyIndex=history.length-1;}const status=$('#saveStatus');status.textContent='Salvando';status.classList.add('saving');MindStorage.saveMap(JSON.parse(snap)).then(()=>{status.textContent='Salvo';status.classList.remove('saving')}).catch(()=>{status.textContent='Não foi possível salvar';status.classList.remove('saving')});updateFavorite();}
function restore(raw){state=normalize(typeof raw==='string'?JSON.parse(raw):raw);selectedId=state.rootId;$('#mapTitle').value=state.title;render();}
function render(){if(!state)return;canvas.innerHTML='';Object.values(state.nodes).forEach(n=>{if(!hidden(n))canvas.append(renderNode(n));});renderEdges();applyView();renderMinimap();if(currentScreen==='outline')renderOutline();updateInspector();}
function renderNode(n){const el=document.createElement('article');el.className=`node${n.id===state.rootId?' root':''}${n.id===selectedId?' selected':''}${n.task.done?' done':''}`;el.dataset.id=n.id;el.style.left=`${n.x}px`;el.style.top=`${n.y}px`;el.style.setProperty('--branch',branchColor(n));el.tabIndex=0;
 const text=document.createElement('div');text.className='node-text';text.textContent=n.text;el.append(text);
 const meta=[];if(n.note)meta.push('▤ nota');if(n.link)meta.push('↗ link');if(n.task.assignee||n.task.due)meta.push(n.task.done?'✓ concluída':'◷ tarefa');if(n.comments.length)meta.push(`◌ ${n.comments.length}`);if(meta.length){const m=document.createElement('div');m.className='node-meta';meta.forEach(v=>{const s=document.createElement('span');s.textContent=v;m.append(s)});el.append(m)}
 if(children(n.id).length){const b=document.createElement('button');b.className='collapse-btn';b.textContent=n.collapsed?'+':'−';b.onclick=e=>{e.stopPropagation();n.collapsed=!n.collapsed;commit();render()};el.append(b)}
 el.onclick=e=>{e.stopPropagation();select(n.id)};el.ondblclick=e=>{e.stopPropagation();editNode(n,el)};el.onmousedown=e=>startDrag(e,n,el);return el;
}
function center(n){const el=canvas.querySelector(`[data-id="${n.id}"]`);return{x:n.x+(el?.offsetWidth||130)/2,y:n.y+(el?.offsetHeight||45)/2};}
function curve(a,b,cls='edge-path',color=branchColor(b),label=''){const p=document.createElementNS('http://www.w3.org/2000/svg','path'),c1=center(a),c2=center(b),dx=(c2.x-c1.x)*.5;p.setAttribute('d',`M ${c1.x} ${c1.y} C ${c1.x+dx} ${c1.y}, ${c2.x-dx} ${c2.y}, ${c2.x} ${c2.y}`);p.setAttribute('class',cls);p.setAttribute('stroke',color);edges.append(p);if(label){const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',(c1.x+c2.x)/2);t.setAttribute('y',(c1.y+c2.y)/2-7);t.setAttribute('class','edge-label');t.textContent=label;edges.append(t)}}
function renderEdges(){edges.innerHTML='';Object.values(state.nodes).forEach(n=>{const p=state.nodes[n.parentId];if(p&&!hidden(n))curve(p,n)});state.connections.forEach(c=>{const a=state.nodes[c.from],b=state.nodes[c.to];if(a&&b&&!hidden(a)&&!hidden(b))curve(a,b,'edge-path cross-edge','#7c8799',c.label||'')});}
function select(id,open=false){selectedId=id;$$('.node').forEach(el=>el.classList.toggle('selected',el.dataset.id===id));updateInspector();if(open)$('#inspector').classList.add('open');if(connectFrom&&id&&id!==connectFrom){state.connections.push({id:uid(),from:connectFrom,to:id,label:'relaciona-se'});cancelConnect();toast('Conexão criada');commit();render();}}
function editNode(n,el){if(editingId)return;editingId=n.id;const t=el.querySelector('.node-text');t.contentEditable='true';t.focus();document.execCommand('selectAll',false,null);const finish=()=>{n.text=t.textContent.trim()||n.text;editingId=null;commit();render()};t.onblur=finish;t.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();t.blur()}if(e.key==='Escape')t.blur();e.stopPropagation()};}
function addNode(parentId,sibling=false,at=null){let parent=state.nodes[parentId];if(sibling&&parent.parentId)parent=state.nodes[parent.parentId];const n=node('Novo tópico',parent.id);const kids=children(parent.id),side=parent.x>=state.nodes[state.rootId].x?1:-1;n.x=at?.x??parent.x+(parent.id===state.rootId?(kids.length%2?330:-330):side*235);n.y=at?.y??parent.y+(kids.length-Math.max(0,kids.length-1)/2)*82;state.nodes[n.id]=n;selectedId=n.id;commit();render();setTimeout(()=>{const el=canvas.querySelector(`[data-id="${n.id}"]`);if(el)editNode(n,el)},20);}
function removeSelected(){if(!selectedId||selectedId===state.rootId){toast('O tópico central não pode ser excluído');return}const target=state.nodes[selectedId],count=children(selectedId).length;showDialog('Excluir tópico?','CONFIRMAR EXCLUSÃO',`<p><strong>${escapeHtml(target.text)}</strong>${count?` e seus ${count} subtópico${count>1?'s':''}`:''} serão removidos do mapa.</p><div class="dialog-actions"><button class="quiet-button" id="cancelNodeDelete">Cancelar</button><button class="danger-button" id="confirmNodeDelete">Excluir</button></div>`);$('#cancelNodeDelete').onclick=()=>$('#dialog').hidden=true;$('#confirmNodeDelete').onclick=()=>{deleteBranch(selectedId);$('#dialog').hidden=true;toast('Tópico excluído')}}
function deleteBranch(id){const ids=[id];for(let i=0;i<ids.length;i++)children(ids[i]).forEach(n=>ids.push(n.id));const parent=state.nodes[id].parentId;ids.forEach(nodeId=>delete state.nodes[nodeId]);state.connections=state.connections.filter(c=>!ids.includes(c.from)&&!ids.includes(c.to));selectedId=parent;commit();render()}
function startDrag(e,n,el){if(e.button||editingId)return;e.stopPropagation();select(n.id);drag={id:n.id,sx:e.clientX,sy:e.clientY,x:n.x,y:n.y,moved:false};el.classList.add('dragging')}
document.addEventListener('mousemove',e=>{if(drag){const n=state.nodes[drag.id],dx=(e.clientX-drag.sx)/view.scale,dy=(e.clientY-drag.sy)/view.scale;n.x=drag.x+dx;n.y=drag.y+dy;drag.moved|=Math.abs(dx)>2||Math.abs(dy)>2;const el=canvas.querySelector(`[data-id="${n.id}"]`);el.style.left=`${n.x}px`;el.style.top=`${n.y}px`;renderEdges();renderMinimap()}else if(pan){view.x=pan.x+e.clientX-pan.sx;view.y=pan.y+e.clientY-pan.sy;applyView();renderMinimap()}});
document.addEventListener('mouseup',()=>{if(drag?.moved)commit();drag=null;pan=null});
wrap.addEventListener('mousedown',e=>{if(e.target===wrap||e.target===canvas||e.target===edges){select(null);pan={sx:e.clientX,sy:e.clientY,x:view.x,y:view.y}}});
wrap.addEventListener('dblclick',e=>{if(e.target!==wrap&&e.target!==canvas)return;const r=wrap.getBoundingClientRect();addNode(state.rootId,false,{x:(e.clientX-r.left-view.x)/view.scale,y:(e.clientY-r.top-view.y)/view.scale})});
wrap.addEventListener('wheel',e=>{e.preventDefault();const r=wrap.getBoundingClientRect();zoomAt(e.clientX-r.left,e.clientY-r.top,-e.deltaY*.001)},{passive:false});
function zoomAt(mx,my,d){const old=view.scale,next=Math.min(2.3,Math.max(.25,old*(1+d))),wx=(mx-view.x)/old,wy=(my-view.y)/old;view={x:mx-wx*next,y:my-wy*next,scale:next};applyView();renderMinimap()}
function applyView(){canvas.style.transform=edges.style.transform=`translate(${view.x}px,${view.y}px) scale(${view.scale})`;$('#zoomLabel').textContent=`${Math.round(view.scale*100)}%`}
function fit(){const ns=Object.values(state.nodes).filter(n=>!hidden(n));if(!ns.length)return;const xs=ns.map(n=>n.x),ys=ns.map(n=>n.y),minX=Math.min(...xs)-100,maxX=Math.max(...xs)+300,minY=Math.min(...ys)-100,maxY=Math.max(...ys)+140,r=wrap.getBoundingClientRect(),w=maxX-minX,h=maxY-minY,ideal=Math.min(r.width/w,r.height/h,1.25),s=r.width<600?Math.max(.55,ideal):ideal;view={scale:s,x:-minX*s+(r.width-w*s)/2,y:-minY*s+(r.height-h*s)/2};applyView();renderMinimap()}
function renderMinimap(){if(!state)return;const c=$('#minimapCanvas'),ctx=c.getContext('2d'),w=c.width=c.clientWidth,h=c.height=c.clientHeight,sx=w/6000,sy=h/4000;ctx.clearRect(0,0,w,h);Object.values(state.nodes).filter(n=>!hidden(n)).forEach(n=>{ctx.fillStyle=branchColor(n);ctx.fillRect(n.x*sx,n.y*sy,6,5)});const vp=$('#minimapViewport');vp.style.cssText=`left:${-view.x/view.scale*sx}px;top:${-view.y/view.scale*sy}px;width:${wrap.clientWidth/view.scale*sx}px;height:${wrap.clientHeight/view.scale*sy}px`}
function renderOutline(){const out=$('#outlineTree');out.innerHTML='';$('#outlineTitle').textContent=state.title;const visit=(id,depth=0)=>{const n=state.nodes[id];if(!n)return;const row=document.createElement('div');row.className='outline-row';row.style.setProperty('--depth',depth);row.style.setProperty('--branch',branchColor(n));const toggle=document.createElement('button');toggle.textContent=children(id).length?(n.collapsed?'＋':'−'):'·';toggle.onclick=()=>{n.collapsed=!n.collapsed;commit();renderOutline()};const input=document.createElement('input');input.value=n.text;input.onchange=()=>{n.text=input.value||n.text;commit();render()};const add=document.createElement('button');add.textContent='＋';add.title='Adicionar subtópico';add.onclick=()=>addNode(id);row.append(toggle,input,add);out.append(row);if(!n.collapsed)children(id).forEach(c=>visit(c.id,depth+1))};visit(state.rootId)}
function updateInspector(){const n=state?.nodes[selectedId];if(!n)return;$('#inspectorTitle').textContent=n.text;$('#nodeText').value=n.text;$('#nodeNote').value=n.note||'';$('#nodeLink').value=n.link||'';$('#taskAssignee').value=n.task.assignee||'';$('#taskDue').value=n.task.due||'';$('#taskDone').checked=!!n.task.done;$('#commentCount').textContent=n.comments.length;const list=$('#commentsList');list.innerHTML='';n.comments.forEach(c=>{const d=document.createElement('div');d.className='comment';d.textContent=c.text;const s=document.createElement('small');s.textContent=`Miguel · ${new Date(c.at).toLocaleString('pt-BR')}`;d.append(s);list.append(d)});}
function openInspector(tab='details'){if(!selectedId){toast('Selecione um tópico primeiro');return}$('#inspector').classList.add('open');switchInspector(tab==='comments'?'comments':'details')}
function switchInspector(tab){$$('[data-inspector-tab]').forEach(b=>b.classList.toggle('active',b.dataset.inspectorTab===tab));$('#detailsPanel').hidden=tab!=='details';$('#commentsPanel').hidden=tab!=='comments'}
function scheduleDetailsSave(){clearTimeout(detailsTimer);const status=$('#saveStatus');status.textContent='Editando';detailsTimer=setTimeout(()=>{if(state?.nodes[selectedId])saveDetails(false)},450)}
function saveDetails(notify=true){const n=state.nodes[selectedId];n.text=$('#nodeText').value.trim()||n.text;n.note=$('#nodeNote').value.trim();n.link=$('#nodeLink').value.trim();n.task={assignee:$('#taskAssignee').value.trim(),due:$('#taskDue').value,done:$('#taskDone').checked};commit();if(notify){render();toast('Tópico atualizado')}else{const el=canvas.querySelector(`[data-id="${n.id}"]`);if(el){el.querySelector('.node-text').textContent=n.text;el.classList.toggle('done',n.task.done);renderEdges()}$('#inspectorTitle').textContent=n.text}}
function cancelConnect(){connectFrom=null;$('#connectionNotice').hidden=true;$('#btnConnect').classList.remove('active')}
function renderHome(filter=currentFilter){currentFilter=filter;currentScreen='home';$('#homeView').hidden=false;$('#mapView').hidden=true;$('#outlineView').hidden=true;$('#editorToolbar').hidden=true;$('#inspector').classList.remove('open');const labels={recent:'Mapas recentes',all:'Todos os mapas',favorite:'Favoritos',team:'Mapas da equipe'};$('#mapsHeading').textContent=labels[filter]||'Mapas';MindStorage.listMaps().then(maps=>{const total=maps.length;$('#recentCount').textContent=total;if(filter==='favorite')maps=maps.filter(m=>m.favorite);if(filter==='team')maps=[];if(searchQuery)maps=maps.filter(m=>(m.title||'').toLocaleLowerCase('pt-BR').includes(searchQuery));const grid=$('#homeMaps');grid.innerHTML='';if(!maps.length){const message=searchQuery?'Nenhum mapa corresponde à sua busca.':filter==='favorite'?'Favorite um mapa para encontrá-lo rapidamente aqui.':filter==='team'?'Mapas compartilhados aparecerão aqui quando a colaboração online estiver conectada.':'Crie seu primeiro mapa para começar.';grid.innerHTML=`<div class="empty-card"><div><strong>Nenhum mapa aqui</strong><br>${message}</div></div>`;return}maps.forEach(m=>{const card=document.createElement('article');card.className='map-card';card.tabIndex=0;card.setAttribute('aria-label',`Abrir ${m.title||'mapa sem título'}`);card.innerHTML='<div class="map-preview"><div class="mini-root"></div><i></i><i></i><i></i></div><div class="map-card-body"><strong></strong><small></small></div><div class="card-actions"><button class="duplicate-map" title="Duplicar mapa" aria-label="Duplicar mapa">⧉</button><button class="delete-map" title="Excluir mapa" aria-label="Excluir mapa">⌫</button></div>';card.querySelector('strong').textContent=m.title||'Sem título';card.querySelector('small').textContent=`Atualizado ${relativeDate(m.updatedAt)}`;card.onclick=async e=>{if(e.target.closest('.card-actions'))return;openMap(await MindStorage.loadMap(m.id))};card.onkeydown=e=>{if(e.key==='Enter')card.click()};card.querySelector('.duplicate-map').onclick=async e=>{e.stopPropagation();const copy=normalize(await MindStorage.loadMap(m.id));copy.id=mid();copy.title=`${copy.title} — cópia`;await MindStorage.saveMap(copy);toast('Mapa duplicado');renderHome()};card.querySelector('.delete-map').onclick=e=>{e.stopPropagation();confirmDeleteMap(m)};grid.append(card)})})}
function openMap(data){restore(data);history=[snapshot()];historyIndex=0;currentScreen='map';$('#homeView').hidden=true;$('#mapView').hidden=false;$('#outlineView').hidden=true;$('#editorToolbar').hidden=false;MindStorage.setLastOpenedId(state.id);setTimeout(fit,20)}
function newMap(){openMap(starter());commit();toast('Novo mapa criado')}
function relativeDate(d){if(!d)return'agora';const mins=Math.floor((Date.now()-new Date(d))/60000);return mins<1?'agora':mins<60?`há ${mins} min`:mins<1440?`há ${Math.floor(mins/60)} h`:new Date(d).toLocaleDateString('pt-BR')}
function updateFavorite(){if(!state)return;$('#btnFavorite').textContent=state.favorite?'◆':'◇'}
function showDialog(title,eyebrow,html){$('#dialogTitle').textContent=title;$('#dialogEyebrow').textContent=eyebrow;$('#dialogBody').innerHTML=html;$('#dialog').hidden=false;setTimeout(()=>$('#dialog').querySelector('button,input')?.focus(),0)}
function confirmDeleteMap(map){showDialog('Excluir este mapa?','CONFIRMAR EXCLUSÃO',`<p><strong>${escapeHtml(map.title||'Mapa sem título')}</strong> será removido deste navegador. Esta ação não pode ser desfeita.</p><div class="dialog-actions"><button class="quiet-button" id="cancelDelete">Cancelar</button><button class="danger-button" id="confirmDelete">Excluir mapa</button></div>`);$('#cancelDelete').onclick=()=>$('#dialog').hidden=true;$('#confirmDelete').onclick=async()=>{await MindStorage.deleteMap(map.id);$('#dialog').hidden=true;toast('Mapa excluído');renderHome()}}
function escapeHtml(value){const el=document.createElement('div');el.textContent=value;return el.innerHTML}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),1800)}
function exportJson(){const a=document.createElement('a'),blob=new Blob([snapshot()],{type:'application/json'});a.href=URL.createObjectURL(blob);a.download=`${state.title.replace(/[^\w-]+/g,'_')}.json`;a.click();URL.revokeObjectURL(a.href);toast('Mapa exportado')}
function importFile(file){const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);d.id=mid();openMap(d);commit();toast('Mapa importado')}catch{toast('Este arquivo não é um mapa válido')}};r.readAsText(file)}
function present(){document.documentElement.requestFullscreen?.();$('#inspector').classList.remove('open');fit();toast('Modo apresentação ativado')}
// Controls
$('#btnNewMap').onclick=$('#btnNewMapHome').onclick=newMap;$('#btnHome').onclick=()=>renderHome();$('#btnMobileMenu').onclick=()=>$('#sidebar').classList.toggle('open');
$$('.nav-item[data-filter]').forEach(b=>b.onclick=()=>{$$('.nav-item').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderHome(b.dataset.filter);$('#sidebar').classList.remove('open')});
$('#btnAddChild').onclick=()=>selectedId?addNode(selectedId):toast('Selecione um tópico');$('#btnAddSibling').onclick=()=>selectedId?addNode(selectedId,true):toast('Selecione um tópico');$('#btnDelete').onclick=removeSelected;
$('#btnConnect').onclick=()=>{if(!selectedId)return toast('Selecione o primeiro tópico');connectFrom=selectedId;$('#connectionNotice').hidden=false;$('#btnConnect').classList.add('active')};$('#btnCancelConnect').onclick=cancelConnect;
$$('[data-panel]').forEach(b=>b.onclick=()=>openInspector(b.dataset.panel==='comments'?'comments':'details'));$('#btnCloseInspector').onclick=()=>{$('#inspector').classList.remove('open');render()};$$('[data-inspector-tab]').forEach(b=>b.onclick=()=>switchInspector(b.dataset.inspectorTab));
['#nodeText','#nodeNote','#nodeLink','#taskAssignee','#taskDue','#taskDone'].forEach(selector=>$(selector).addEventListener('input',scheduleDetailsSave));
$('#btnAddComment').onclick=()=>{const text=$('#newComment').value.trim();if(!text)return;state.nodes[selectedId].comments.push({id:uid(),text,at:new Date().toISOString()});$('#newComment').value='';commit();updateInspector();toast('Comentário adicionado')};
COLORS.forEach(c=>{const b=document.createElement('button');b.className='swatch';b.style.background=c;b.title=c;b.onclick=()=>{if(selectedId){state.nodes[selectedId].color=c;commit();render()}};$('#colorSwatches').append(b)});
$('.view-switch [data-view="map"]').onclick=()=>{currentScreen='map';$('#mapView').hidden=false;$('#outlineView').hidden=true;$$('.view-switch button').forEach(b=>b.classList.toggle('active',b.dataset.view==='map'));setTimeout(fit,20)};
$('.view-switch [data-view="outline"]').onclick=()=>{currentScreen='outline';$('#mapView').hidden=true;$('#outlineView').hidden=false;$$('.view-switch button').forEach(b=>b.classList.toggle('active',b.dataset.view==='outline'));renderOutline()};
$('#btnZoomIn').onclick=()=>zoomAt(wrap.clientWidth/2,wrap.clientHeight/2,.2);$('#btnZoomOut').onclick=()=>zoomAt(wrap.clientWidth/2,wrap.clientHeight/2,-.2);$('#btnZoomReset').onclick=fit;
$('#btnUndo').onclick=()=>{if(historyIndex>0){historyIndex--;restore(history[historyIndex]);MindStorage.saveMap(JSON.parse(history[historyIndex]));toast('Alteração desfeita')}};$('#btnRedo').onclick=()=>{if(historyIndex<history.length-1){historyIndex++;restore(history[historyIndex]);MindStorage.saveMap(JSON.parse(history[historyIndex]));toast('Alteração refeita')}};
$('#mapTitle').onchange=e=>{state.title=e.target.value.trim()||'Mapa sem título';commit()};$('#btnFavorite').onclick=()=>{state.favorite=!state.favorite;commit();toast(state.favorite?'Adicionado aos favoritos':'Removido dos favoritos')};$('#btnTheme').onclick=()=>{const dark=document.documentElement.dataset.theme==='dark';document.documentElement.dataset.theme=dark?'light':'dark';localStorage.setItem('mastermind.theme',dark?'light':'dark');render()};
$('#btnExport').onclick=()=>showDialog('Levar este mapa com você','EXPORTAR','<button class="dialog-option" id="exportJson"><span>{ }</span><div><strong>Arquivo do Master Mind</strong><small>JSON editável e importável</small></div></button><button class="dialog-option" id="printPdf"><span>▤</span><div><strong>Imprimir ou salvar em PDF</strong><small>Use as opções do navegador</small></div></button>');
$('#dialogBody').addEventListener('click',e=>{if(e.target.closest('#exportJson')){exportJson();$('#dialog').hidden=true}if(e.target.closest('#printPdf')){window.print();$('#dialog').hidden=true}});$('#btnCloseDialog').onclick=()=>$('#dialog').hidden=true;$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').hidden=true};
$('#btnShare').onclick=()=>showDialog('Compartilhar mapa','COLABORAÇÃO','<p>O projeto está no modo local. Exporte o arquivo para colaborar agora ou conecte um backend para colaboração em tempo real.</p><div class="share-link"><input value="Armazenado somente neste navegador" readonly><button class="share-button" id="copyState">Entendi</button></div>');
$('#dialogBody').addEventListener('click',e=>{if(e.target.closest('#copyState'))$('#dialog').hidden=true});$('#btnPresent').onclick=present;
$('#btnTemplates').onclick=()=>showDialog('Começar com um modelo','MODELOS','<button class="dialog-option template" data-template="plan"><span>⌁</span><div><strong>Plano estratégico</strong><small>Visão, projetos, recursos e próximos passos</small></div></button><button class="dialog-option template" data-template="blank"><span>○</span><div><strong>Mapa em branco</strong><small>Uma ideia central pronta para crescer</small></div></button>');
$('#dialogBody').addEventListener('click',e=>{const t=e.target.closest('.template');if(!t)return;$('#dialog').hidden=true;if(t.dataset.template==='plan')newMap();else{const r=node('Ideia central',null,null,2820,1900);openMap({id:mid(),title:'Novo mapa',nodes:{[r.id]:r},rootId:r.id,connections:[]});commit()}});
$('#btnHelp').onclick=()=>showDialog('Atalhos para pensar mais rápido','AJUDA','<div class="shortcut-list"><div><kbd>Tab</kbd><span>Criar subtópico</span></div><div><kbd>Enter</kbd><span>Criar tópico irmão</span></div><div><kbd>Duplo clique</kbd><span>Editar um tópico</span></div><div><kbd>Delete</kbd><span>Excluir tópico selecionado</span></div><div><kbd>⌘ Z</kbd><span>Desfazer</span></div><div><kbd>⌘ S</kbd><span>Exportar mapa</span></div><div><kbd>Esc</kbd><span>Cancelar ou fechar</span></div></div>');
$('.section-heading button').onclick=()=>toast('As coleções personalizadas chegam com a sincronização online');$$('.collection-item').forEach(b=>b.onclick=()=>toast('Esta coleção ainda não possui mapas'));
$('#btnTrash').onclick=()=>toast('A lixeira estará disponível com a sincronização online');$('#btnImportHome').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=e=>{if(e.target.files[0])importFile(e.target.files[0]);e.target.value=''};$('#mapSearch').oninput=e=>{searchQuery=e.target.value.trim().toLocaleLowerCase('pt-BR');renderHome()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#dialog').hidden){$('#dialog').hidden=true;return}cancelConnect();$('#inspector').classList.remove('open')}if(editingId||['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?$('#btnRedo'):$('#btnUndo')).click()}else if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();exportJson()}else if(e.key==='Tab'&&selectedId){e.preventDefault();addNode(selectedId)}else if(e.key==='Enter'&&selectedId){e.preventDefault();addNode(selectedId,true)}else if(['Delete','Backspace'].includes(e.key))removeSelected();else if(e.key==='?')$('#btnHelp').click()});
window.addEventListener('resize',()=>{renderMinimap();if(innerWidth>900)$('#sidebar').classList.remove('open')});
async function boot(){document.documentElement.dataset.theme=localStorage.getItem('mastermind.theme')||'light';const last=MindStorage.getLastOpenedId();let data=last?await MindStorage.loadMap(last):null;if(!data){data=starter();await MindStorage.saveMap(data)}openMap(data)}boot();
})();
